mapper.select:
SELECT a.date, COUNT(DISTINCT a.user_id) AS count
FROM (
    SELECT DATE_FORMAT(CONVERT_TZ(d.created_at, '+00:00', '+08:00'), '%Y-%m-%d') AS date, d.user_id
    FROM diet_records d WHERE d.deleted_at IS NULL AND d.created_at >= #{rangeStart} AND d.created_at < #{rangeEnd}
    UNION ALL
    SELECT DATE_FORMAT(CONVERT_TZ(s.created_at, '+00:00', '+08:00'), '%Y-%m-%d') AS date, s.user_id
    FROM slot_spins s WHERE s.created_at >= #{rangeStart} AND s.created_at < #{rangeEnd}
) a JOIN users u ON u.id = a.user_id JOIN roles r ON r.id = u.role_id
WHERE r.code = 'USER'
GROUP BY a.date
